INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1680918, 227183, 33889, '<td valign="top">Looks like an Ansel Adams style photo.  Very nice and on topic!</td>', 'Looks like an Ansel Adams style photo.  Very nice and on topic!', '2005-09-07 01:08:22.000000', NULL, 1),
(1680928, 228034, 35545, '<td valign="top">Good picture.  Good title.</td>', 'Good picture.  Good title.', '2005-09-07 01:09:20.000000', NULL, 1),
(1680930, 225688, 15711, '<td valign="top">HEE HEE That''s pretty darn clever.  Hope the parrot excaped.  A for originality. Beautiful cat (and parrot).</td>', 'HEE HEE That''s pretty darn clever.  Hope the parrot excaped.  A for originality. Beautiful cat (and parrot).', '2005-09-07 01:09:52.000000', NULL, 1),
(1680932, 227647, 15711, '<td valign="top">What an unusual butterfly.  Looks almost like somebody painted paper!  Very nice shot. I like the DOF very much.</td>', 'What an unusual butterfly.  Looks almost like somebody painted paper!  Very nice shot. I like the DOF very much.', '2005-09-07 01:10:29.000000', NULL, 1),
(1680935, 228314, 33889, '<td valign="top">Kind of pushing it on the topic...</td>', 'Kind of pushing it on the topic...', '2005-09-07 01:11:18.000000', NULL, 1),
(1680939, 228252, 15711, '<td valign="top">Nice shot.  I''d like to see it zoomed in more. I see that you were trying to incorporate the whole branch but I think I''d like to see a tighter shot of the budding pine cone. Good DOF</td>', 'Nice shot.  I''d like to see it zoomed in more. I see that you were trying to incorporate the whole branch but I think I''d like to see a tighter shot of the budding pine cone. Good DOF', '2005-09-07 01:11:48.000000', NULL, 1),
(1680941, 227396, 26189, '<td valign="top">Nice color!  Althought the title of this challenge is "branch" your eye goes to the woman walking...which I like.  Great job!!!!</td>', 'Nice color!  Althought the title of this challenge is "branch" your eye goes to the woman walking...which I like.  Great job!!!!', '2005-09-07 01:11:57.000000', NULL, 1),
(1680946, 225224, 39560, '<td valign="top">looks to be over-processed and OOF. Also B&amp;W does it no justice. Hard to make out what it actually is.</td>', 'looks to be over-processed and OOF. Also B&W does it no justice. Hard to make out what it actually is.', '2005-09-07 01:12:46.000000', NULL, 1),
(1680950, 228274, 33889, '<td valign="top">Good colors and composition.  Taking the shot straight on in the midday sun leaves the image a bit flat though.  If you could have caught this in the early morning or in the evening you would have had more to work with on this one.</td>', 'Good colors and composition.  Taking the shot straight on in the midday sun leaves the image a bit flat though.  If you could have caught this in the early morning or in the evening you would have had more to work with on this one.', '2005-09-07 01:13:28.000000', NULL, 1),
(1680956, 227024, 25906, '<td valign="top">Great shot. I hope you had fun shooting this one. <br/>10</td>', 'Great shot. I hope you had fun shooting this one. 10', '2005-09-07 01:13:53.000000', NULL, 1),
(1680958, 225149, 15711, '<td valign="top">Nice title. I like the still one along with the dragonfly in flight.</td>', 'Nice title. I like the still one along with the dragonfly in flight.', '2005-09-07 01:14:06.000000', NULL, 1),
(1680963, 227063, 33889, '<td valign="top">Fine bird pic, pushing it on the topic though.</td>', 'Fine bird pic, pushing it on the topic though.', '2005-09-07 01:15:00.000000', NULL, 1),
(1680965, 228156, 15711, '<td valign="top">Neat pyramid effect.  Unusual. The golden sunny tones are nice against the black reflection.</td>', 'Neat pyramid effect.  Unusual. The golden sunny tones are nice against the black reflection.', '2005-09-07 01:15:13.000000', NULL, 1),
(1680966, 227579, 24495, '<td valign="top">The Branch, which should be the main subject for this challenge, is out of focus / Blurred. It appears as if waterfall is the main subject! 6.</td>', 'The Branch, which should be the main subject for this challenge, is out of focus / Blurred. It appears as if waterfall is the main subject! 6.', '2005-09-07 01:15:19.000000', NULL, 1),
(1680967, 225635, 33889, '<td valign="top">Sexy!  8</td>', 'Sexy!  8', '2005-09-07 01:15:20.000000', NULL, 1),
(1680972, 226467, 15711, '<td valign="top">Cool lens flare. I like the gnarled tree and roots.</td>', 'Cool lens flare. I like the gnarled tree and roots.', '2005-09-07 01:16:02.000000', NULL, 1),
(1680973, 228261, 39560, '<td valign="top">Very nice portrait. It needs the branch incorporated into the shot. She could be swinging from anything.</td>', 'Very nice portrait. It needs the branch incorporated into the shot. She could be swinging from anything.', '2005-09-07 01:16:23.000000', NULL, 1),
(1680976, 227091, 15711, '<td valign="top">Interesting and not expected.  I like the negative space usage.  Nice shadowing and light.</td>', 'Interesting and not expected.  I like the negative space usage.  Nice shadowing and light.', '2005-09-07 01:16:37.000000', NULL, 1),
