INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1681788, 226624, 42837, '<td valign="top">For such a pared back composition, the knot or ''eye'' as you call it seems indistinct and too closely placed to the tear in the bark and circular mark just to the right to really stand out, even with the very narrow DOF I''m afraid.</td>', 'For such a pared back composition, the knot or ''eye'' as you call it seems indistinct and too closely placed to the tear in the bark and circular mark just to the right to really stand out, even with the very narrow DOF I''m afraid.', '2005-09-07 07:52:37.000000', NULL, 1),
(1681792, 227661, 43148, '<td valign="top">know the challenge was branch, but this photo would be much better with the top third (maybe even half) cropped off IMO</td>', 'know the challenge was branch, but this photo would be much better with the top third (maybe even half) cropped off IMO', '2005-09-07 07:54:48.000000', NULL, 1),
(1681793, 227903, 43148, '<td valign="top">branches are there but not featured, nice pic though</td>', 'branches are there but not featured, nice pic though', '2005-09-07 07:55:25.000000', NULL, 1),
(1681796, 227592, 29474, '<td valign="top">Great photo. Well taken and composed. Maybe the crop is a bit tight. But really a stretch to fit it into the challenge.</td>', 'Great photo. Well taken and composed. Maybe the crop is a bit tight. But really a stretch to fit it into the challenge.', '2005-09-07 07:57:36.000000', NULL, 1),
(1681799, 227143, 42837, '<td valign="top">The duck has just enough ''camoflague'' with the shadows so as not to dominate the subject of the image I think. The branch could be more dominant though so as to really seem to be covering the duck, Nice lines in the branches and textures in the water although it took a while for me to notice the rain, which could be more obvious.</td>', 'The duck has just enough ''camoflague'' with the shadows so as not to dominate the subject of the image I think. The branch could be more dominant though so as to really seem to be covering the duck, Nice lines in the branches and textures in the water although it took a while for me to notice the rain, which could be more obvious.', '2005-09-07 07:59:43.000000', NULL, 1),
(1681800, 227944, 42837, '<td valign="top">I like this a lot. I wonder if it would have been even stronger if it were a portrait instead?</td>', 'I like this a lot. I wonder if it would have been even stronger if it were a portrait instead?', '2005-09-07 08:03:11.000000', NULL, 1),
(1681802, 228254, 29474, '<td valign="top">A good photograph that is spoiled by the trees, Also, a bit of a squeeze to fit it into the challenge.</td>', 'A good photograph that is spoiled by the trees, Also, a bit of a squeeze to fit it into the challenge.', '2005-09-07 08:05:06.000000', NULL, 1),
