(1685565, 225812, 32084, '<td valign="top">Nice twist on the theme and well executed.</td>', 'Nice twist on the theme and well executed.', '2005-09-08 01:26:00.000000', NULL, 1),
(1685566, 225209, 42837, '<td valign="top">The branch is lost in the leaves. The uniformity of their pattern is dominating the shot and isn''t broken up enough.</td>', 'The branch is lost in the leaves. The uniformity of their pattern is dominating the shot and isn''t broken up enough.', '2005-09-08 01:26:44.000000', NULL, 1),
