(1685569, 228331, 32084, '<td valign="top">Nice detail and interesting lighting.</td>', 'Nice detail and interesting lighting.', '2005-09-08 01:27:42.000000', NULL, 1),
(1685571, 228331, 42957, '<td valign="top">The two dots in the sky on the photo bother me.  Looks like your lense needs cleaning.</td>', 'The two dots in the sky on the photo bother me.  Looks like your lense needs cleaning.', '2005-09-08 01:28:13.000000', NULL, 1),
(1685572, 227180, 32084, '<td valign="top">Very nice.  I wonder how this would look in B&amp;W - possbily quite Ansel-ish.</td>', 'Very nice.  I wonder how this would look in B&W - possbily quite Ansel-ish.', '2005-09-08 01:28:18.000000', NULL, 1),
(1685575, 226740, 39243, '<td valign="top">Too much green for my tastes.  but such a great photograph beautiful. <br/>7</td>', 'Too much green for my tastes.  but such a great photograph beautiful. 7', '2005-09-08 01:29:34.000000', NULL, 1),
