(1688632, 226080, 41522, '<td valign="top">I see the branching ... I feel the lighting/processing is a bit harsh.</td>', 'I see the branching ... I feel the lighting/processing is a bit harsh.', '2005-09-08 22:13:41.000000', NULL, 1),
(1688635, 228287, 41522, '<td valign="top">It would have been so nice if you could have found an angle that isolated the tree.</td>', 'It would have been so nice if you could have found an angle that isolated the tree.', '2005-09-08 22:14:31.000000', NULL, 1),
