(1690082, 226212, 20115, '<td valign="top">simply beautiful</td>', 'simply beautiful', '2005-09-09 11:20:16.000000', NULL, 1),
(1690091, 225480, 40584, '<td valign="top">nice reflection in water to ''complete'' the hidden half of tree.</td>', 'nice reflection in water to ''complete'' the hidden half of tree.', '2005-09-09 11:24:32.000000', NULL, 1),
(1690096, 228259, 40584, '<td valign="top">one of my favorites, so far!  crisp and clean without harsh lines.  super shot!</td>', 'one of my favorites, so far!  crisp and clean without harsh lines.  super shot!', '2005-09-09 11:26:25.000000', NULL, 1),
