(1690102, 225532, 40584, '<td valign="top">love the colors and treatment you''ve done!  a real beauty!</td>', 'love the colors and treatment you''ve done!  a real beauty!', '2005-09-09 11:28:55.000000', NULL, 1),
(1690106, 225635, 40584, '<td valign="top">LOL !  What''s not to love about that!</td>', 'LOL !  What''s not to love about that!', '2005-09-09 11:29:35.000000', NULL, 1),
