INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1693931, 225625, 33672, '<td valign="top">Seems a bit over sharpened. The DOF is great as well as the capture and title</td>', 'Seems a bit over sharpened. The DOF is great as well as the capture and title', '2005-09-10 23:35:13.000000', NULL, 1),
(1693933, 228287, 33672, '<td valign="top">Great work.  I really like this.</td>', 'Great work.  I really like this.', '2005-09-10 23:35:44.000000', NULL, 1),
(1693945, 228149, 2000, '<td valign="top">I rate this shot two palms up... or a 7.</td>', 'I rate this shot two palms up... or a 7.', '2005-09-10 23:44:00.000000', NULL, 1),
(1693947, 228256, 42984, '<td valign="top">One of the best 9</td>', 'One of the best 9', '2005-09-10 23:46:52.000000', NULL, 1),
(1693950, 228211, 2000, '<td valign="top">I think the background detail is too strong in this shot... maybe a bit of USM would soften it up a bit.  As it is now, I''m getting a moire (image movement) from the over-high detail.</td>', 'I think the background detail is too strong in this shot... maybe a bit of USM would soften it up a bit.  As it is now, I''m getting a moire (image movement) from the over-high detail.', '2005-09-10 23:47:31.000000', NULL, 1),
(1693953, 226969, 2000, '<td valign="top">This would be a good entry for portait... but I''m getting the family tree reference.</td>', 'This would be a good entry for portait... but I''m getting the family tree reference.', '2005-09-10 23:48:36.000000', NULL, 1),
(1693955, 227908, 2000, '<td valign="top">I feel upside down in this shot... even if it''s right-side up.  The sun looks a bit hot, so a polarizer/ND filter may have helped.</td>', 'I feel upside down in this shot... even if it''s right-side up.  The sun looks a bit hot, so a polarizer/ND filter may have helped.', '2005-09-10 23:50:08.000000', NULL, 1),
(1693958, 226565, 2000, '<td valign="top">The maximum size for any side of your photo is 640px... this is 350px on the long side - just over 1/2 the maximum.  Submiting a small shot makes it hard to see and tough to judge... content and colorwise it''s good.  that size thing hurts a lot here.</td>', 'The maximum size for any side of your photo is 640px... this is 350px on the long side - just over 1/2 the maximum.  Submiting a small shot makes it hard to see and tough to judge... content and colorwise it''s good.  that size thing hurts a lot here.', '2005-09-10 23:51:54.000000', NULL, 1),
(1693961, 228018, 2000, '<td valign="top">I wonder why this looks so noisy... the concept is good, and it fits the challenge.</td>', 'I wonder why this looks so noisy... the concept is good, and it fits the challenge.', '2005-09-10 23:52:34.000000', NULL, 1),
(1693962, 228009, 2000, '<td valign="top">Cool colors, and very nice contrast.</td>', 'Cool colors, and very nice contrast.', '2005-09-10 23:53:17.000000', NULL, 1),
(1693965, 227606, 2000, '<td valign="top">That is a beautiful shot of a spiderweb... I haven''t seen one that dewey before.</td>', 'That is a beautiful shot of a spiderweb... I haven''t seen one that dewey before.', '2005-09-10 23:55:40.000000', NULL, 1),
(1693971, 227931, 2000, '<td valign="top">Stuttgart Airport??  If I''m right about the location, I fully get the branch reference.  But the green color makes this looks like ''Matrix.''  Nice concept.</td>', 'Stuttgart Airport??  If I''m right about the location, I fully get the branch reference.  But the green color makes this looks like ''Matrix.''  Nice concept.', '2005-09-10 23:58:28.000000', NULL, 1),
(1693975, 225651, 2000, '<td valign="top">Nice web shot... I hope you explained how you get them so well in here.  A touch of color would be welcome, but this is very good as is too.</td>', 'Nice web shot... I hope you explained how you get them so well in here.  A touch of color would be welcome, but this is very good as is too.', '2005-09-11 00:00:01.000000', NULL, 1),
(1693991, 228318, 2000, '<td valign="top">This kind of reminds me of Edward Scissorhands.  I think this needs a hair more light, just so the branches are a bit more emphacized.</td>', 'This kind of reminds me of Edward Scissorhands.  I think this needs a hair more light, just so the branches are a bit more emphacized.', '2005-09-11 00:03:27.000000', NULL, 1),
(1693999, 227004, 2000, '<td valign="top">The maximum size for one side of your photo is 640px, and this is 375px on it''s long side.  Even the best shot becomes very difficult to see at this small of a size.  Looking at this shot now, the branches on the guy''s back are very indistinct.</td>', 'The maximum size for one side of your photo is 640px, and this is 375px on it''s long side.  Even the best shot becomes very difficult to see at this small of a size.  Looking at this shot now, the branches on the guy''s back are very indistinct.', '2005-09-11 00:05:53.000000', NULL, 1),
(1694004, 228202, 2000, '<td valign="top">Good use of ''natural'' framing for this shot.  You captured an interesting tree, and made an interesting photo while doing it.</td>', 'Good use of ''natural'' framing for this shot.  You captured an interesting tree, and made an interesting photo while doing it.', '2005-09-11 00:07:09.000000', NULL, 1),
