(1702503, 225852, 39243, '<td valign="top">wow - beautiful shot 7</td>', 'wow - beautiful shot 7', '2005-09-13 03:17:24.000000', NULL, 1),
(1702534, 228024, 41548, '<td valign="top">Like it a lot. I would have liked it more without the lightpost but well...Anyway, it''s my best rated one in this contest.</td>', 'Like it a lot. I would have liked it more without the lightpost but well...Anyway, it''s my best rated one in this contest.', '2005-09-13 03:39:53.000000', NULL, 1),
