INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1706918, 225983, 29240, '<td valign="top">Well done brudder, moving up 20 odd places a challenge, you will get the blue soon :)</td>', 'Well done brudder, moving up 20 odd places a challenge, you will get the blue soon :)', '2005-09-14 03:04:16.000000', NULL, 0),
(1706931, 226131, 37430, '<td valign="top">For many of those who asked - when, where and what ...<br/> <br/>This photo was clicked in Himalayas in India (Manali in HP to be precise). It was not intended for challenge but the timings were to my favour. These are actually trees with fog/cloud drifting. Did not do much of post processing but for cropping, desaturation and increasing the contrast.</td>', 'For many of those who asked - when, where and what ... This photo was clicked in Himalayas in India (Manali in HP to be precise). It was not intended for challenge but the timings were to my favour. These are actually trees with fog/cloud drifting. Did not do much of post processing but for cropping, desaturation and increasing the contrast.', '2005-09-14 03:08:08.000000', NULL, 0),
(1706933, 226212, 25355, '<td valign="top">This had ribbon-winner written all over it (metophorically speaking, of course). Congratulations.</td>', 'This had ribbon-winner written all over it (metophorically speaking, of course). Congratulations.', '2005-09-14 03:08:27.000000', NULL, 0),
(1707011, 226467, 6349, '<td valign="top">i cannot believe this didn''t ribbon!</td>', 'i cannot believe this didn''t ribbon!', '2005-09-14 03:26:59.000000', NULL, 0),
